package org.dromara.property.charge.receivable.service.impl;
import org.dromara.common.core.exception.ServiceException; import org.dromara.property.charge.binding.domain.ChargeBinding; import org.dromara.property.charge.receivable.domain.bo.ReceivableGenerateBo; import org.dromara.property.charge.receivable.mapper.*; import org.dromara.property.scope.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import java.time.YearMonth; import java.util.List; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class ReceivableGenerationServiceSecurityTest { @Mock PropertyProjectScopeService scope; @Mock ReceivableGenerationMapper generation; @Mock ReceivableBatchMapper batches; @Mock ReceivableBindingGenerationWorker worker; ReceivableGenerationServiceImpl service;
 @BeforeEach void setUp(){service=new ReceivableGenerationServiceImpl(scope,generation,batches,worker);}
 @Test void deniedProjectNeverCreatesBatch(){doThrow(new ServiceException("deny")).when(scope).assertBusinessAccess(101L,PropertyBusinessDomain.FINANCE,ProjectBusinessAction.WRITE);assertThrows(ServiceException.class,()->service.generate(bo(101L,YearMonth.now().toString())));verifyNoInteractions(generation,batches,worker);}
 @Test void superAdminPathUsesExistingScopeBypassContract(){when(generation.selectProjectRoomBindings(101L)).thenReturn(java.util.List.of());var result=service.generate(bo(101L,YearMonth.now().toString()));verify(scope).assertBusinessAccess(101L,PropertyBusinessDomain.FINANCE,ProjectBusinessAction.WRITE);InOrder order=inOrder(batches);order.verify(batches).insert(any(org.dromara.property.charge.receivable.domain.ReceivableBatch.class));order.verify(batches).markStarted(anyLong());order.verify(batches).finish(any());assertEquals("SUCCESS",result.getStatus());}
 @Test void rejectsMoreThanThreeFutureMonthsBeforeAccess(){assertThrows(ServiceException.class,()->service.generate(bo(101L,YearMonth.now().plusMonths(4).toString())));verifyNoInteractions(scope);}
 @Test void sameRoomWithTwoChargeBindingsGeneratesBothIndependently(){ChargeBinding property=binding(11L,1001L,201L),sanitation=binding(12L,1001L,202L);when(generation.selectProjectRoomBindings(101L)).thenReturn(List.of(property,sanitation));when(worker.generate(anyLong(),eq(101L),anyLong(),any())).thenReturn(BindingGenerationOutcome.of(BindingGenerationOutcome.Type.GENERATED));var result=service.generate(bo(101L,YearMonth.now().toString()));assertEquals(2,result.getScannedCount());assertEquals(2,result.getGeneratedCount());assertEquals(0,result.getSkippedExistingCount());verify(worker).generate(eq(11L),eq(101L),anyLong(),any());verify(worker).generate(eq(12L),eq(101L),anyLong(),any());}
 @Test void mixedCyclesOnSameRoomCountGeneratedAndNotDuePerBinding(){ChargeBinding yearly=binding(21L,1001L,301L),monthly=binding(22L,1001L,302L);when(generation.selectProjectRoomBindings(101L)).thenReturn(List.of(yearly,monthly));when(worker.generate(eq(21L),eq(101L),anyLong(),any())).thenReturn(BindingGenerationOutcome.of(BindingGenerationOutcome.Type.SKIPPED_NOT_DUE));when(worker.generate(eq(22L),eq(101L),anyLong(),any())).thenReturn(BindingGenerationOutcome.of(BindingGenerationOutcome.Type.GENERATED));var result=service.generate(bo(101L,YearMonth.now().toString()));assertEquals(2,result.getScannedCount());assertEquals(1,result.getGeneratedCount());assertEquals(1,result.getSkippedNotDueCount());}
 private ChargeBinding binding(Long id,Long roomId,Long itemId){ChargeBinding b=new ChargeBinding();b.setId(id);b.setProjectId(101L);b.setObjectType("ROOM");b.setObjectId(roomId);b.setChargeItemId(itemId);return b;}
 private ReceivableGenerateBo bo(Long p,String m){ReceivableGenerateBo b=new ReceivableGenerateBo();b.setProjectId(p);b.setGenerateMonth(m);return b;}
}
